/*
 * A273773  Primes p such that no practical number (A005153) exists between p
 *          and its successor.
 * https://oeis.org/A273773
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   A273773 – primes p such that there is no practical number
 *            between p and its successor. The sequence is generated by
 *            scanning primes and testing each gap for practical numbers
 * Range:     u8 n <= 8, u16 n <= 1816, u32 n <= 8509, u64 n <= 8509,
 *            u128 n <= 8509, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>

/* ------------------------------------------------------------------ */
/* Parameters – enlarge the sieve limit until adequate for the test */
/* ------------------------------------------------------------------ */
static const idx_t LIMIT = 20000000ULL;     /* 20 million primes are enough for n≤10000 */

/* ------------------------------------------------------------------ */
/* Prime sieve – stores all primes up to LIMIT in primes[]           */
/* ------------------------------------------------------------------ */
static uint64_t *primes = NULL;   /* array of primes, type uint64_t = idx_t on 64‑bit */
static size_t prime_cnt = 0;

/* ------------------------------------------------------------------ */
/* Sequence cache – cache of found A273773 values                   */
/* ------------------------------------------------------------------ */
static seq_t  *cache     = NULL;
static size_t cache_cap  = 0;
static size_t cache_len  = 0;   /* number of terms stored so far */
static size_t scan_idx   = 0;   /* index of next prime to examine */

/* ------------------------------------------------------------------ */
/* Prime production – simple Eratosthenes sieve                       */
/* ------------------------------------------------------------------ */
static void init_primes(void)
{
    if (primes != NULL)   /* already done */
        return;

    /* Estimate maximum number of primes up to LIMIT by n / ln(n) */
    size_t est_cnt = (size_t)(LIMIT / 13);   /* rough approx for 20 M */
    primes = (uint64_t*)malloc(est_cnt * sizeof(uint64_t));
    if (!primes)
        return;   /* allocation failed – program will fail later */

    bool *comp = (bool*)calloc((size_t)LIMIT + 1, sizeof(bool));
    if (!comp)
        return;   /* allocation failed */

    for (idx_t i = 2; (idx_t)i * (idx_t)i <= LIMIT; ++i)
        if (!comp[i])
            for (idx_t j = i * i; j <= LIMIT; j += i)
                comp[j] = true;

    size_t cnt = 0;
    for (idx_t i = 2; i <= LIMIT; ++i)
        if (!comp[i])
        {
            if (cnt >= est_cnt)   /* grow if needed */
            {
                est_cnt *= 2;
                uint64_t *tmp = (uint64_t*)realloc(primes, est_cnt * sizeof(uint64_t));
                if (!tmp) break;
                primes = tmp;
            }
            primes[cnt++] = (uint64_t)i;
        }
    prime_cnt = cnt;
    free(comp);
}

/* ------------------------------------------------------------------ */
/* Practical number test – uses order of prime factors                 */
/* ------------------------------------------------------------------ */
static bool is_practical(uint64_t n)
{
    if (n == 1) return true;
    uint64_t sum = 1;                 /* product of sigma of processed factors */
    bool first = true;

    uint64_t tmp = n;
    for (size_t i = 0; i < prime_cnt && (uint64_t)primes[i] * (uint64_t)primes[i] <= tmp; ++i)
    {
        uint64_t p = primes[i];
        if (tmp % p == 0)
        {
            uint32_t exp = 0;
            uint64_t pow = 1;
            uint64_t sigma = 1;       /* sigma(p^exp) */
            while (tmp % p == 0)
            {
                tmp /= p;
                ++exp;
                pow *= p;
                sigma += pow;
            }

            if (first)
            {
                if (p != 2)  return false;
                first = false;
            }
            else
            {
                if (p > sum + 1)  return false;
            }
            sum *= sigma;
        }
    }

    if (tmp > 1)  /* remaining prime factor */
    {
        uint64_t p = tmp;
        if (first)
        {
            if (p != 2)  return false;
            first = false;
        }
        else if (p > sum + 1)
            return false;

        uint64_t sigma = 1 + p;
        sum *= sigma;
    }

    return true;
}

/* ------------------------------------------------------------------ */
/* Extend the cached sequence until it contains at least n terms      */
/* ------------------------------------------------------------------ */
static void ensure_cache(idx_t n)
{
    while (cache_len < n)
    {
        if (scan_idx + 1 >= prime_cnt)   /* out of primes – nothing more to add */
            break;

        uint64_t p = primes[scan_idx];
        uint64_t q = primes[scan_idx + 1];
        scan_idx++;

        /* Skip trivial gaps with no interior integers */
        if (q - p <= 1)
            continue;

        bool has_practical = false;
        for (uint64_t v = p + 1; v < q; ++v)
            if (is_practical(v))
            {
                has_practical = true;
                break;
            }

        if (!has_practical)
        {
            if (cache_len >= cache_cap)
            {
                cache_cap = cache_cap ? cache_cap * 2 : 16;
                seq_t *tmp = (seq_t*)realloc(cache, cache_cap * sizeof(seq_t));
                if (!tmp) break;  /* allocation failed */
                cache = tmp;
            }
            cache[cache_len++] = (seq_t)p;
        }
    }
}

/* ------------------------------------------------------------------ */
/* Public function – returns the nth term of the sequence             */
/* ------------------------------------------------------------------ */
seq_t a(idx_t n)
{
    if (n == 0)  return 0;   /* sequence is 1‑based; undefined for 0 */
    init_primes();
    ensure_cache(n);
    return cache[n - 1];
}
